import{J as e,n as t,ot as n,q as r}from"./chunks/framework.Dl75AD2m.js";var i=JSON.parse(`{"title":"Class: CornerCache","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: CornerCache"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/CornerCache"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/worldgen/classes/CornerCache"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/worldgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/worldgen/classes/CornerCache.md","filePath":"api/@jsprismarine/worldgen/classes/CornerCache.md","lastUpdated":1794206055000}`),a={name:`api/@jsprismarine/worldgen/classes/CornerCache.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/worldgen</a> / CornerCache</p><h1 id="class-cornercache" tabindex="-1">Class: CornerCache <a class="header-anchor" href="#class-cornercache" aria-label="Permalink to “Class: CornerCache”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/47cf4b608a0a6b613286621162172984d6d0d693/packages/worldgen/src/density/SampleContext.ts#L76" target="_blank" rel="noreferrer">density/SampleContext.ts:76</a></p><p>The cell-corner values an <code>interpolated</code> function has already computed.</p><p>Corners sit on a regular lattice, so the slot is the cell index masked per axis rather than a hash of the position. A chunk&#39;s lattice is 5 by 5 cells across and 49 up at vanilla&#39;s cell size, which lands inside one window of the 8 by 8 by 64 the masks carve out, so no two corners a chunk is working on can collide. A hashed index collided often enough to compute a chunk&#39;s 1225 corners 6139 times, and a corner is the most expensive thing the density stack does.</p><p>The window is sized to that working set and no larger, because every <code>interpolated</code> node builds one of these per chunk and the zeroing and collection of the buffers is paid per chunk too. The cache is direct-mapped, so a position outside the window evicts rather than grows, and the stored cell indices are compared exactly before a value is reused. Eviction costs a recomputation, never an answer, because a density function tree is deterministic for one context. Java fills a whole cell grid up front; this covers the same working set without having to visit the chunk in Java&#39;s cell order.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new CornerCache</strong>(): <code>CornerCache</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>CornerCache</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="clear" tabindex="-1">clear() <a class="header-anchor" href="#clear" aria-label="Permalink to “clear()”">​</a></h3><blockquote><p><strong>clear</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/47cf4b608a0a6b613286621162172984d6d0d693/packages/worldgen/src/density/SampleContext.ts#L122" target="_blank" rel="noreferrer">density/SampleContext.ts:122</a></p><p>Drops every memoized corner.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="getorcompute" tabindex="-1">getOrCompute() <a class="header-anchor" href="#getorcompute" aria-label="Permalink to “getOrCompute()”">​</a></h3><blockquote><p><strong>getOrCompute</strong>(<code>context</code>, <code>input</code>, <code>cellX</code>, <code>cellY</code>, <code>cellZ</code>, <code>x</code>, <code>y</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/47cf4b608a0a6b613286621162172984d6d0d693/packages/worldgen/src/density/SampleContext.ts#L89" target="_blank" rel="noreferrer">density/SampleContext.ts:89</a></p><p>Returns the corner value, computing it through <code>input</code> when the slot does not hold it.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to “context”">​</a></h5><p><a href="./SampleContext.html"><code>SampleContext</code></a></p><h5 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to “input”">​</a></h5><p><a href="./../#densitysampler"><code>DensitySampler</code></a></p><h5 id="cellx" tabindex="-1">cellX <a class="header-anchor" href="#cellx" aria-label="Permalink to “cellX”">​</a></h5><p><code>number</code></p><p>The corner&#39;s lattice index across x, which is <code>x / cellSizeXz</code>. The caller already has it, and passing it keeps the division out of this path.</p><h5 id="celly" tabindex="-1">cellY <a class="header-anchor" href="#celly" aria-label="Permalink to “cellY”">​</a></h5><p><code>number</code></p><h5 id="cellz" tabindex="-1">cellZ <a class="header-anchor" href="#cellz" aria-label="Permalink to “cellZ”">​</a></h5><p><code>number</code></p><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p>`,43)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};